review = []
for r in records_in_ID_order:
    if r.period != "Permian":
        continue
    if r.region not in {"Europe", "eastern North America"}:
        continue
    if r.large_feathery_ferns_present:
        continue
    if r.p_new <= r.p_old or r.t_new <= r.t_old:
        continue
    i = length(review)
    append r to review
    while i > 0:
        if r.t_new < review[i - 1].t_new:
            review[i] = review[i - 1]
            i = i - 1
        else:
            break
    review[i] = r
return review
```

